import{_ as a,o as i,c as e,aj as o}from"./chunks/framework.CvEpoKXn.js";const u=JSON.parse('{"title":"Cursor 使用 MCP：从概念到配置实战","description":"用一篇文章讲清 MCP 是什么、有哪些核心概念与工作流程，并手把手教你在 Cursor 里配置 .cursor/mcp.json、验证工具可用、排查常见问题。","frontmatter":{"title":"Cursor 使用 MCP：从概念到配置实战","date":"2026-04-25T00:00:00.000Z","cover":"https://cdn.jsdelivr.net/gh/oyuovo/image@img/img/bgrandom18.jpg","description":"用一篇文章讲清 MCP 是什么、有哪些核心概念与工作流程，并手把手教你在 Cursor 里配置 .cursor/mcp.json、验证工具可用、排查常见问题。","tags":["Cursor","MCP","AI"],"categories":"编程基础"},"headers":[],"relativePath":"posts/Cursor-MCP使用指南.md","filePath":"posts/Cursor-MCP使用指南.md","lastUpdated":1788960575000}'),t={name:"posts/Cursor-MCP使用指南.md"};function l(n,s,r,p,h,c){return i(),e("div",null,[...s[0]||(s[0]=[o(`<blockquote><p>把「只会聊天」升级为「能真实调用工具」</p></blockquote><hr><h1 id="第一部分-mcp-是什么-核心概念与工作流程" tabindex="-1">第一部分：MCP 是什么？核心概念与工作流程 <a class="header-anchor" href="#第一部分-mcp-是什么-核心概念与工作流程" aria-label="Permalink to &quot;第一部分：MCP 是什么？核心概念与工作流程&quot;">​</a></h1><h2 id="mcp-的含义" tabindex="-1">MCP 的含义 <a class="header-anchor" href="#mcp-的含义" aria-label="Permalink to &quot;MCP 的含义&quot;">​</a></h2><p>**MCP（Model Context Protocol，模型上下文协议）**是一套开放协议，用来把「外部能力」以统一方式接入到 AI Agent 中。<br> 它解决的是一个非常具体的问题：<strong>让模型不仅能读你给的上下文，还能通过标准化接口去“调用工具 / 取资源 / 做动作”。</strong></p><p>在 Cursor 里，你可以把 MCP 理解成：</p><ul><li>你配置并运行若干个 <strong>MCP Server</strong></li><li>每个 Server 暴露一组 <strong>Tools（工具）</strong> 和/或 <strong>Resources（资源）</strong></li><li>Cursor 作为 <strong>MCP Client</strong>，把这些能力呈现给 Agent</li><li>Agent 在合适的时候发起工具调用（通常需要你确认），把结果再用于生成回答/改代码</li></ul><h2 id="mcp-的核心概念" tabindex="-1">MCP 的核心概念 <a class="header-anchor" href="#mcp-的核心概念" aria-label="Permalink to &quot;MCP 的核心概念&quot;">​</a></h2><h3 id="_1-mcp-client" tabindex="-1">1）MCP Client <a class="header-anchor" href="#_1-mcp-client" aria-label="Permalink to &quot;1）MCP Client&quot;">​</a></h3><p>在我们的语境里，<strong>Cursor 就是 MCP Client</strong>。它负责：</p><ul><li>启动/连接 MCP Server</li><li>拉取 server 的能力清单（tools/resources）</li><li>在对话中代表 Agent 发起调用，并展示请求参数与返回结果</li></ul><h3 id="_2-mcp-server" tabindex="-1">2）MCP Server <a class="header-anchor" href="#_2-mcp-server" aria-label="Permalink to &quot;2）MCP Server&quot;">​</a></h3><p><strong>MCP Server 是一个进程（本地）或一个远程服务</strong>，它向 client 提供能力：</p><ul><li>本地进程常见：<code>node</code> / <code>python</code> / <code>npx</code> / <code>docker run ...</code></li><li>远程常见：HTTP/SSE 风格的 URL（不同实现可能叫 <code>sse</code> / <code>streamableHttp</code> 等）</li></ul><h3 id="_3-tools" tabindex="-1">3）Tools <a class="header-anchor" href="#_3-tools" aria-label="Permalink to &quot;3）Tools&quot;">​</a></h3><p>Tool 是 <strong>“可被调用的动作”</strong>，通常带有：</p><ul><li><strong>名称</strong>（例如 <code>filesystem.readFile</code>、<code>github.search_issues</code>）</li><li><strong>输入参数 schema</strong>（JSON 结构）</li><li><strong>输出</strong>（JSON/文本）</li></ul><p>常见 Tool 类型：</p><ul><li><strong>读写文件/目录</strong>（注意：很多 server 会做路径白名单限制）</li><li><strong>访问第三方 API</strong>（GitHub、数据库、CI、内部平台）</li><li><strong>浏览器自动化/抓取</strong>（例如 Playwright 类服务器）</li></ul><h3 id="_4-resources" tabindex="-1">4）Resources <a class="header-anchor" href="#_4-resources" aria-label="Permalink to &quot;4）Resources&quot;">​</a></h3><p>Resource 更像 <strong>“可被读取的上下文素材”</strong>，例如：</p><ul><li>只读数据源（配置、文档、某个系统的查询结果）</li><li>能被列出、按 URI 获取的内容</li></ul><h3 id="_5-transport" tabindex="-1">5）Transport <a class="header-anchor" href="#_5-transport" aria-label="Permalink to &quot;5）Transport&quot;">​</a></h3><p>Cursor 常见支持两类：</p><ul><li><strong>stdio</strong>：启动本地命令，靠标准输入输出通信（最常见、最容易上手）</li><li><strong>HTTP/SSE</strong>：连接远程服务（团队/企业内部工具常用）</li></ul><blockquote><p>你不需要记住协议细节，只要记住：stdio = 跑命令，HTTP/SSE = 连 URL。</p></blockquote><h2 id="mcp-的核心工作流程" tabindex="-1">MCP 的核心工作流程 <a class="header-anchor" href="#mcp-的核心工作流程" aria-label="Permalink to &quot;MCP 的核心工作流程&quot;">​</a></h2><p>为了把“概念”落到 Cursor 的真实使用上，下面用 Cursor 官方文档的两张截图来对照关键步骤：<br> 先出现「工具调用确认」，再出现「工具调用结果」。</p><img src="https://cursor.com/docs-static/images/context/mcp/tool-confirm.png" alt="Cursor MCP 工具调用确认弹窗（官方文档截图）" style="max-width:100%;height:auto;"><img src="https://cursor.com/docs-static/images/context/mcp/tool-call.png" alt="Cursor MCP 工具调用结果展示（官方文档截图）" style="max-width:100%;height:auto;"><blockquote><p>图源：Cursor 官方文档 <code>cursor.com/docs/mcp.md</code></p></blockquote><p>把一次完整的链路拆开看：</p><ol><li>你在 <code>mcp.json</code> 里配置 server（或通过 Cursor UI 配置）</li><li>Cursor 启动/连接 server，并拉取 tools/resources 列表</li><li>你在 Composer 的 Agent 模式下提需求（例如“用 GitHub 工具查最近 10 条 issue”）</li><li>Agent 判断需要用工具，发起 tool call（多数情况下会弹出权限确认）</li><li>Cursor 执行调用，把结果回传给 Agent</li><li>Agent 用返回结果生成最终输出（回答、改代码、产出报告等）</li></ol><h2 id="什么时候-mcp-真正-值回票价" tabindex="-1">什么时候 MCP 真正“值回票价” <a class="header-anchor" href="#什么时候-mcp-真正-值回票价" aria-label="Permalink to &quot;什么时候 MCP 真正“值回票价”&quot;">​</a></h2><p>下面这些场景，MCP 的提升是质变：</p><ul><li><strong>数据不在本地文件里</strong>：GitHub、数据库、线上日志、内部 API</li><li><strong>需要“可验证”的信息</strong>：能直接查询/列出/对比，而不是凭模型猜</li><li><strong>需要执行动作</strong>：创建 issue、跑脚本、批量改文件、生成报告</li></ul><hr><h1 id="第二部分-cursor-里的-mcp-配置与测试使用" tabindex="-1">第二部分：Cursor 里的 MCP 配置与测试使用 <a class="header-anchor" href="#第二部分-cursor-里的-mcp-配置与测试使用" aria-label="Permalink to &quot;第二部分：Cursor 里的 MCP 配置与测试使用&quot;">​</a></h1><h2 id="_1-两种配置范围-项目级-vs-全局" tabindex="-1">1）两种配置范围：项目级 vs 全局 <a class="header-anchor" href="#_1-两种配置范围-项目级-vs-全局" aria-label="Permalink to &quot;1）两种配置范围：项目级 vs 全局&quot;">​</a></h2><p>Cursor 支持把 MCP 配置放在两个位置（常用实践）：</p><ul><li><strong>项目级</strong>：把配置放到项目根目录的 <code>.cursor/mcp.json</code><br> 适合：团队共享、项目专用工具（建议 commit，但不要 commit 明文密钥）</li><li><strong>全局级</strong>：把配置放到用户目录的 <code>~/.cursor/mcp.json</code><br> 适合：个人通用工具（例如个人 GitHub token）</li></ul><p>在 Windows 上，全局路径通常是：</p><ul><li><code>%USERPROFILE%\\.cursor\\mcp.json</code></li></ul><h2 id="_2-用-cursor-mcp-json-配一个最小可用示例-stdio-本地命令" tabindex="-1">2）用 <code>.cursor/mcp.json</code> 配一个最小可用示例（stdio 本地命令） <a class="header-anchor" href="#_2-用-cursor-mcp-json-配一个最小可用示例-stdio-本地命令" aria-label="Permalink to &quot;2）用 \`.cursor/mcp.json\` 配一个最小可用示例（stdio 本地命令）&quot;">​</a></h2><p>在项目根目录创建文件：<code>.cursor/mcp.json</code></p><p>示例（文件系统 server，限制在当前项目目录）：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;filesystem&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;npx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;-y&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;@modelcontextprotocol/server-filesystem&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">        &quot;\${workspaceFolder}&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>要点：</p><ul><li><code>mcpServers</code> 是根字段，少了它 Cursor 可能直接忽略整份配置</li><li><code>args</code> 用数组而不是一整条字符串，更稳定</li><li>路径尽量用 <code>\${workspaceFolder}</code> 这类插值，避免手写硬编码</li></ul><h2 id="_3-关于密钥的配置" tabindex="-1">3）关于密钥的配置 <a class="header-anchor" href="#_3-关于密钥的配置" aria-label="Permalink to &quot;3）关于密钥的配置&quot;">​</a></h2><p>以 GitHub server 为例（<strong>不要把 token 写死在文件里</strong>）：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;github&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;npx&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;-y&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;@modelcontextprotocol/server-github&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;env&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;GITHUB_PERSONAL_ACCESS_TOKEN&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;\${env:GITHUB_TOKEN}&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">      }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>然后在你的系统环境变量里配置 <code>GITHUB_TOKEN</code>（或用 PowerShell 当前会话临时设置）：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">GITHUB_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ghp_xxx&quot;</span></span></code></pre></div><blockquote><p>习惯建议：把 token 做成最小权限、可随时吊销的专用 token；并把 <code>.cursor/mcp.json</code> 当成“基础设施配置”来审查。</p></blockquote><h2 id="_4-改完配置后要做什么-重启与检查工具列表" tabindex="-1">4）改完配置后要做什么：重启与检查工具列表 <a class="header-anchor" href="#_4-改完配置后要做什么-重启与检查工具列表" aria-label="Permalink to &quot;4）改完配置后要做什么：重启与检查工具列表&quot;">​</a></h2><p><strong>MCP server 通常在 Cursor 启动时加载</strong>。因此改了 <code>mcp.json</code> 后，建议：</p><ul><li>完全退出并重启 Cursor</li><li>打开设置页里 MCP 相关区域，确认 server 状态为已连接，并能看到 tool 列表</li></ul><p>如果 server 支持认证流程（OAuth 或内置 auth 工具），按提示完成即可。</p><p>下面两张图来自 Cursor 官方文档，展示了「工具调用确认」与「工具调用结果」在 UI 里的样子（便于你对照自己是否配置成功）：</p><img src="https://cursor.com/docs-static/images/context/mcp/tool-confirm.png" alt="Cursor MCP 工具调用确认弹窗（官方文档截图）" style="max-width:100%;height:auto;"><img src="https://cursor.com/docs-static/images/context/mcp/tool-call.png" alt="Cursor MCP 工具调用结果展示（官方文档截图）" style="max-width:100%;height:auto;"><h2 id="_5-在-cursor-里测试-mcp-一段-可复制的验收提示词" tabindex="-1">5）在 Cursor 里测试 MCP：一段“可复制的验收提示词” <a class="header-anchor" href="#_5-在-cursor-里测试-mcp-一段-可复制的验收提示词" aria-label="Permalink to &quot;5）在 Cursor 里测试 MCP：一段“可复制的验收提示词”&quot;">​</a></h2><p>在 Composer 中切换到 <strong>Agent</strong>（不是 Ask），然后直接发这段：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>列出你当前可用的 MCP tools（按 server 分组）。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>然后使用 filesystem 的工具：</span></span>
<span class="line"><span>1) 列出项目根目录下的顶层文件/文件夹</span></span>
<span class="line"><span>2) 读取 docs/posts 目录下任意一篇文章的前 30 行</span></span>
<span class="line"><span>最后告诉我：哪些工具调用需要人工确认、哪些可以设置为自动运行。</span></span></code></pre></div><p>看到以下信号基本就算成功：</p><ul><li>能列出 MCP tools</li><li>能实际读到文件内容</li><li>对话里能展开看到 tool call 的参数与返回值</li></ul><h2 id="_6-常见问题排查" tabindex="-1">6）常见问题排查 <a class="header-anchor" href="#_6-常见问题排查" aria-label="Permalink to &quot;6）常见问题排查&quot;">​</a></h2><h3 id="server-没出现-tools-列表为空" tabindex="-1">“Server 没出现 / Tools 列表为空” <a class="header-anchor" href="#server-没出现-tools-列表为空" aria-label="Permalink to &quot;“Server 没出现 / Tools 列表为空”&quot;">​</a></h3><ul><li>检查 <code>.cursor/mcp.json</code> 是否是合法 JSON（尤其逗号、引号）</li><li>检查根字段是否为 <code>mcpServers</code></li><li>重启 Cursor（不要只关窗口）</li></ul><h3 id="command-not-found-npx-找不到" tabindex="-1">“command not found / npx 找不到” <a class="header-anchor" href="#command-not-found-npx-找不到" aria-label="Permalink to &quot;“command not found / npx 找不到”&quot;">​</a></h3><ul><li>本机需要可用的 Node.js（很多社区 MCP server 依赖 Node 18+）</li><li>尝试在终端运行同样命令，确认环境变量 PATH 没问题</li></ul><h3 id="tools-出现了-但-agent-不会用" tabindex="-1">“Tools 出现了，但 Agent 不会用” <a class="header-anchor" href="#tools-出现了-但-agent-不会用" aria-label="Permalink to &quot;“Tools 出现了，但 Agent 不会用”&quot;">​</a></h3><ul><li>确保你在 <strong>Composer 的 Agent 模式</strong>下</li><li>在提示词里显式点名工具/任务（例如“使用 github 工具搜索 issue”）</li></ul><h3 id="认证失败-401-403" tabindex="-1">“认证失败 / 401 / 403” <a class="header-anchor" href="#认证失败-401-403" aria-label="Permalink to &quot;“认证失败 / 401 / 403”&quot;">​</a></h3><ul><li>token 权限不够或过期</li><li>变量没生效：确认 <code>\${env:...}</code> 对应的环境变量确实存在</li></ul><h2 id="_7-安全建议" tabindex="-1">7）安全建议 <a class="header-anchor" href="#_7-安全建议" aria-label="Permalink to &quot;7）安全建议&quot;">​</a></h2><ul><li><strong>不要 commit 明文密钥</strong>（token、API key、cookie）</li><li>尽量用 <code>\${env:XXX}</code> 引用环境变量</li><li>把 <code>.cursor/mcp.json</code> 的变更当成“脚本/CI 配置”级别来 code review</li><li>只安装/启用你信任的 server（MCP server 本质上是在你的环境里跑命令/访问网络）</li></ul><hr><h1 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h1><ul><li>MCP 的价值在于：把外部能力标准化接入 Agent，让“写代码”变成“能查、能跑、能验证”的闭环</li><li>在 Cursor 里落地，核心就两件事：<strong>写好 <code>mcp.json</code> + 在 Composer/Agent 里验收工具调用</strong></li></ul>`,81)])])}const k=a(t,[["render",l]]);export{u as __pageData,k as default};
